      freezes: [{ method: "GET", path: "/v1/freezes" }, { method: "POST", path: "/v1/freezes" }, { method: "GET", path: "/v1/freezes/:freezeId" }, { method: "POST", path: "/v1/freezes/:freezeId/lift" }],
      gates: [{ method: "GET", path: "/v1/gates" }, { method: "POST", path: "/v1/recommendations/:recommendationId/gate" }, { method: "GET", path: "/v1/gates/:gateDecisionId" }],
      identity: [{ method: "GET", path: "/v0/tenants/me/api-keys" }, { method: "POST", path: "/v0/tenants/me/api-keys" }, { method: "GET", path: "/v0/tenants/me/api-keys/:keyId" }, { method: "DELETE", path: "/v0/tenants/me/api-keys/:keyId" }, { method: "GET", path: "/v0/tenants/me/users" }, { method: "POST", path: "/v0/tenants/me/users" }, { method: "GET", path: "/v0/tenants/me/users/:userId" }, { method: "PATCH", path: "/v0/tenants/me/users/:userId" }, { method: "POST", path: "/v0/tenants/me/users/:userId/disable" }, { method: "POST", path: "/v0/tenants/me/users/:userId/enable" }, { method: "POST", path: "/v0/auth/login" }, { method: "GET", path: "/v0/auth/me" }, { method: "PATCH", path: "/v0/auth/me" }, { method: "POST", path: "/v0/auth/refresh" }, { method: "POST", path: "/v0/auth/logout" }],
